from work import core
core(48,[('binary water/glycerin solvent limiting water-water hydrogen bonds','enables','low-temperature durability and antidrying of PVA/GEL thermogalvanic gel','These features result from the use of a binary H2O/GL (glycerin) solvent to limit hydrogen bonding between water molecules.','joint_outcome'),('breath-environment temperature difference across gel patch','generates','electrical signals for self-powered respiratory monitoring','The prepared thermogalvanic gel patch is capable of easily converting physiological data into understandable electrical impulses using the temperature difference between the ambient environment and the heat produced by human breathing, realizing a simple self-powered respiratory monitoring strategy for the first time.','reported_function')],scope='application_sensing')
core(49,[('Onsager-flux thermocell simulation','predicts','short-circuit current, maximum power and conversion efficiency','The simulation is shown to correctly predict the short circuit current, maximum power output, and power conversion efficiency.','model_prediction_validated')],reason='浓度与间距依赖仅说shown，未给方向，不建立具体增减关系。',scope='measurement_method_model')
core(50,[('β-cyclodextrin host-guest interaction in ferrocenecarboxylate thermocell','increases magnitude of negative','Seebeck coefficient','The Seebeck coefficient of the cell was improved from -0.86 to -1.20 mV K-1 by the addition of beta-cyclodextrin. Isothermal titration calorimetry and a theoretical investigation demonstrated that the host-guest interaction increased the Seebeck coefficient.','negative_magnitude_improvement')])
core(51,[('decoupled heat and electricity conduction in dual-cell heat engine','allows independent optimization of','conversion efficiency','In electrochemical dual-cell heat engines, the conduction of heat and electricity are fully decoupled, allowing their independent optimisation to maximise the conversion efficiency.','theoretical_design'),('dual-cell electrochemical system','requires','flow control responding to electrical current','Our theoretical analysis revealed for the first time that in the dual-cell electrochemical system, the flow rate must be controlled as a response to the electrical current, and conversion efficiency no longer depend on the conventional ther-moelectric figure-of-merit.','theoretical_requirement'),('dual-cell conversion efficiency','does not depend on','conventional thermoelectric figure of merit','Our theoretical analysis revealed for the first time that in the dual-cell electrochemical system, the flow rate must be controlled as a response to the electrical current, and conversion efficiency no longer depend on the conventional ther-moelectric figure-of-merit.','theoretical_negation')],scope='thermodynamics')
core(52,[('wound-dressing temperature gradient','generates','electrical stimulus','Here we report a solution that harnesses the temperature gradient between the wound and dressing to generate an electric stimulus that provides active wound healing management.','reported_function'),('TGC dressing exogenous electric field','promotes','wound healing','Moreover, the TGC dressing generates an exogenous electric field, promoting the spontaneous acceleration of wound healing.','author_claim')],scope='application_sensing')
core(53,[('Bmim+/H2PO4− thermodiffusion and Fe2+/Fe3+ thermogalvanic effect','jointly produce','negative Seebeck coefficient−6.50mV/K','The synergistic interplay of ion thermodiffusion (Bmim+/H2PO4- ) and thermogalvanic effect (Fe2+/Fe3+) yielded a high n-type Seebeck coefficient of -6.50 mV center dot K- 1, enabling efficient heatto-electric conversion (76.1 mV, 144.3 nW at Delta T = 12 K).','joint_attribution'),('rapid voltage surge','triggers','self-signaled fire alarm within2s','Remarkably, RTIG enabled self-signaled fire alarm activation within 2 s triggered by a rapid voltage surge (74.65 mV) and exhibited exceptional flame retardancy (LOI = 59%, 26.5% reduction of PHRR) attributed to phosphorus-iron synergistic char formation.','reported_function'),('phosphorus-iron synergistic char formation','causes','flame retardancy','Remarkably, RTIG enabled self-signaled fire alarm activation within 2 s triggered by a rapid voltage surge (74.65 mV) and exhibited exceptional flame retardancy (LOI = 59%, 26.5% reduction of PHRR) attributed to phosphorus-iron synergistic char formation.','joint_attribution')],scope='application_sensing')
core(54,[('temperature-induced GO pseudocapacitance and Fe2+/Fe3+ thermogalvanic effect','jointly generate','voltage on heating','When heated, the cell generates voltage via a temperature-induced pseudocapacitive effect of graphene oxide and a thermogalvanic effect of Fe2+/Fe3+, and then discharges continuously by oxidizing polyaniline and reducing Fe3+ under isothermal heating till Fe3+ depletion.','joint_mechanism'),('polyaniline oxidation and Fe3+ reduction under isothermal heating','sustain','discharge until Fe3+ depletion','When heated, the cell generates voltage via a temperature-induced pseudocapacitive effect of graphene oxide and a thermogalvanic effect of Fe2+/Fe3+, and then discharges continuously by oxidizing polyaniline and reducing Fe3+ under isothermal heating till Fe3+ depletion.','joint_mechanism_conditional'),('cooling','enables','cell self-regeneration','The cell can be self-regenerated when cooled down.','author_claim')],scope='device_engineering')
core(55,[],reason='综述背景与优化议程，无具体可定位的新机制结论。',scope='review_overview')
core(56,[('Cl− coordination','stabilizes','Cu2+/Cu+ redox species','Herein, we uncover an overlooked thermogalvanic redox reaction between Cu2+ and Cu+ stabilized by Cl- and quantitatively track the progressive reaction process by operando characterization.','author_claim'),('increasing CuCl2 concentration in PVA gels','enhances redox while suppressing','thermodiffusion contribution','In binary polyvinyl alcohol (PVA)-CuCl2 gels, an interactive i-TE coupling effect driven by ion speciation is validated, which exhibits an enhanced thermogalvanic redox as CuCl2 concentrations increase while suppressing the thermodiffusion contribution.','opposing_joint_outcomes'),('tuning ion coordination speciation','enables','large negative thermopower and power density','Correspondingly, a giant thermopower of -30.6 mV K-1 and a remarkable power density of 0.6 mW m-2 K-2 are achieved, respectively, by tuning ion coordination speciation.','author_claim')])
core(57,[('thermogalvanic effect and constant gel elastic modulus','jointly enable','sensor operation under stretching','The sensor operates properly under stretching, which relies on the thermogalvanic effect and constant elastic modulus of hydrogels.','joint_mechanism')],scope='application_sensing')
core(58,[('aqueous biphasic electrolytes','provide different electrode solvation and suppress','thermal convection','The aqueous biphasic electrolytes can not only offer different solvation environment near the electrodes, but also suppress the thermal convection, hence result in improved Se and reduced x.','joint_mechanism'),('different electrode solvation and suppressed convection','jointly improve Seebeck coefficient and reduce','effective thermal conductivity','The aqueous biphasic electrolytes can not only offer different solvation environment near the electrodes, but also suppress the thermal convection, hence result in improved Se and reduced x.','joint_outcomes'),('porous graphite felt electrodes in biphasic thermocell','further improve','output power','Furthermore, with the help of porous graphite felt as electrode material, the output power can be improved over 7 times.','author_claim')])
core(59,[('rapid interfacial solar evaporation','induces','simultaneous salinity and temperature gradients','The rapid interfacial evaporation induces simultaneous salinity and temperature gradient between evaporation surface and bulk water, which enables electricity generation but is not comprehensively utilized.','joint_outcome'),('TGC/RED coupling with spatial layout and composite electrodes','enhances power through','synergistic ion transport','Because of the synergistic ion transport effect, the coupling of TGC and RED enables mutual power enhancement by orders of magnitude based on the rational spatial layout and the fabrication of composite electrodes.','joint_attribution')],scope='device_engineering')
